CREATE POLICY "capture_check_insert" ON "payment_capture_checks" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("payment_capture_checks"."source"=current_setting('rove.capture_source',true) AND "payment_capture_checks"."attempt_id"=NULLIF(current_setting('rove.capture_write',true),'')::uuid);--> statement-breakpoint
CREATE POLICY "capture_check_update" ON "payment_capture_checks" AS PERMISSIVE FOR UPDATE TO public USING ("payment_capture_checks"."source"=current_setting('rove.capture_source',true) AND "payment_capture_checks"."attempt_id"=NULLIF(current_setting('rove.capture_write',true),'')::uuid) WITH CHECK ("payment_capture_checks"."source"=current_setting('rove.capture_source',true) AND "payment_capture_checks"."attempt_id"=NULLIF(current_setting('rove.capture_write',true),'')::uuid);--> statement-breakpoint
